// CHLADNI PLATES
// Grains on a vibrating plate hop about in proportion to how hard the plate is moving under them, so they pile up
// where it is not: the nodal lines. The plate's standing wave is a sum of waves (a square plate's modes, a drum's,
// five- and seven-fold quasicrystals, spirals, ripple interference), and the pitch glides rather than jumps, so
// turning the pitch knob makes the patterns flow into each other while the sand chases them.
// Variables are re-read every frame.

const DOM = 1;                    // plate coordinates run -1..1
const SQUARE_MODES = [[1,2],[1,3],[2,3],[1,4],[2,5],[3,4],[3,5],[2,7],[4,5],[3,7],[4,7],[5,6],[5,8],[6,7],[4,9],[7,8],[6,11],[7,10],[8,9],[9,10],[10,11]];
const DRUM_MODES = [[0,1],[1,1],[2,1],[0,2],[3,1],[1,2],[4,1],[2,2],[0,3],[5,1],[3,2],[1,3],[6,1],[4,2],[2,3],[0,4],[5,2],[3,3],[1,4],[7,1],[4,3]];

const PITCH = { 'a low hum': 0.6, 'a hum': 1.4, 'a murmur': 2.2, 'a song': 3.0, 'a shimmer': 3.9, 'a whistle': 4.8, 'a keen': 5.8, 'a shriek': 7.0 };
const SHAKE = { 'hush': 0.35, 'a whisper': 0.6, 'a hum': 1.0, 'a shiver': 1.5, 'a rattle': 2.3, 'a storm': 3.6 };

// bg: centre and rim of the plate; pos / neg: haze where the plate is up / down; ink: the grains; light: draws dark grains on a pale plate
const FINISH = {
  'brass':        { bg: ['#33270f', '#0f0b05'], pos: [217, 164, 65],  neg: [107, 63, 18],   ink: [246, 236, 208], light: false },
  'slate':        { bg: ['#2d333a', '#0f1215'], pos: [122, 160, 196], neg: [58, 74, 90],    ink: [232, 237, 242], light: false },
  'black mirror': { bg: ['#0b0c11', '#000000'], pos: [106, 124, 255], neg: [255, 90, 122],  ink: [255, 255, 255], light: false },
  'paper drum':   { bg: ['#f1e9d6', '#c9bd9c'], pos: [214, 165, 106], neg: [138, 166, 184], ink: [42, 33, 24],    light: true },
  'copper':       { bg: ['#42200f', '#150a06'], pos: [224, 130, 74],  neg: [47, 107, 106],  ink: [255, 231, 208], light: false },
  'water':        { bg: ['#0c3040', '#041018'], pos: [111, 208, 232], neg: [28, 90, 122],   ink: [232, 251, 255], light: false },
  'bone':         { bg: ['#ece6d8', '#c4baa4'], pos: [184, 166, 138], neg: [138, 143, 152], ink: [58, 52, 43],    light: true },
  'cobalt glass': { bg: ['#0b1659', '#030725'], pos: [106, 140, 255], neg: [176, 76, 255],  ink: [240, 244, 255], light: false }
};

// n: how many grains are in play; size: pixels
const GRAINS = {
  'fine sand':      { n: 16000, size: 1.9 },
  'salt':           { n: 9000,  size: 2.7 },
  'iron filings':   { n: 8000,  size: 6.5 },
  'glitter':        { n: 6500,  size: 3.4 },
  'rice':           { n: 7000,  size: 4.8 },
  'pollen':         { n: 8000,  size: 3.6 },
  'sugar crystals': { n: 7000,  size: 3.2 },
  'ink droplets':   { n: 4500,  size: 3.8 }
};

const MAXG = 16000;
const gx = new Float32Array(MAXG), gy = new Float32Array(MAXG), gAngle = new Float32Array(MAXG), gHue = new Float32Array(MAXG);
let hazeCanvas, hazeCtx, hazeImg;
const FG = 160;                      // the plate's wave is worked out once a frame on this grid; grains and haze both read it
const fa = new Float32Array(FG * FG);
const H = 2 / (FG - 1);
let plateA = 'square plate', plateB = 'square plate', mix = 1;
let q = 3.0, phase = 0, walk = 0, arp = 0;

// the standing wave of one plate at (x, y), pitch q, phase ph, scaled to about -1..1
function wave(plate, x, y, qv, ph) {
  const kappa = Math.PI * (1.5 + 1.15 * qv);
  if (plate === 'square plate') {
    const f = Math.max(0, Math.min(SQUARE_MODES.length - 1.001, qv * 2.2)), i = Math.floor(f), t = f - i;
    const u = (x + 1) / 2, v = (y + 1) / 2;
    const m0 = SQUARE_MODES[i], m1 = SQUARE_MODES[i + 1];
    // the two ways of combining the pair: s = -1 is the classic antisymmetric mode (it always has a diagonal node),
    // s = +1 the symmetric one; the phase slides between them so the same pitch keeps showing new figures
    const s = Math.cos(ph * 0.25 + 0.9);
    const a0 = Math.cos(m0[0] * Math.PI * u) * Math.cos(m0[1] * Math.PI * v) + s * Math.cos(m0[1] * Math.PI * u) * Math.cos(m0[0] * Math.PI * v);
    const a1 = Math.cos(m1[0] * Math.PI * u) * Math.cos(m1[1] * Math.PI * v) + s * Math.cos(m1[1] * Math.PI * u) * Math.cos(m1[0] * Math.PI * v);
    return (a0 * (1 - t) + a1 * t) * 0.55;
  }
  if (plate === 'round drum') {
    const r = Math.sqrt(x * x + y * y);
    if (r > 1) return 1;
    const f = Math.max(0, Math.min(DRUM_MODES.length - 1.001, qv * 2.2)), i = Math.floor(f), t = f - i;
    const th = Math.atan2(y, x) + ph * 0.05;
    const d0 = DRUM_MODES[i], d1 = DRUM_MODES[i + 1];
    const a0 = Math.cos(d0[0] * th) * Math.cos(Math.PI * (d0[1] + 0.25) * r);
    const a1 = Math.cos(d1[0] * th) * Math.cos(Math.PI * (d1[1] + 0.25) * r);
    return a0 * (1 - t) + a1 * t;
  }
  if (plate === 'spiral chime') {
    const r = Math.sqrt(x * x + y * y);
    if (r > 1) return 1;
    const arms = 1 + Math.floor(qv * 0.8);
    return Math.cos(arms * Math.atan2(y, x) + kappa * r * 1.3 - ph * 0.6);
  }
  if (plate === 'ripple tank') {
    const s = [[-0.55, -0.35], [0.6, -0.3], [0.0, 0.62]];
    let a = 0;
    for (let k = 0; k < 3; k++) { const dx = x - s[k][0], dy = y - s[k][1]; a += Math.cos(kappa * 1.4 * Math.sqrt(dx * dx + dy * dy) - ph * 0.5 * (k + 1) * 0.5); }
    return a / 3 * 1.1;
  }
  let dirs = 4;                               // the lattice and quasicrystal plates: plane waves at equal angles
  if (plate === 'square lattice') dirs = 2;
  else if (plate === 'hexagonal lattice') dirs = 3;
  else if (plate === 'five-fold quasicrystal') dirs = 5;
  else if (plate === 'seven-fold quasicrystal') dirs = 7;
  let a = 0;
  for (let j = 0; j < dirs; j++) {
    const ang = (j * Math.PI) / dirs + ph * 0.02;
    a += Math.cos(kappa * (x * Math.cos(ang) + y * Math.sin(ang)) + (ph * 0.7) * (j % 2 ? 1 : -1));
  }
  return a / dirs * (dirs > 3 ? 1.5 : 1.15);
}

function field(x, y) {
  if (mix >= 1) return wave(plateB, x, y, q, phase);
  return wave(plateA, x, y, q, phase) * (1 - mix) + wave(plateB, x, y, q, phase) * mix;
}

function scatter() {
  for (let i = 0; i < MAXG; i++) { gx[i] = Math.random() * 2 - 1; gy[i] = Math.random() * 2 - 1; gAngle[i] = Math.random() * 3.1416; gHue[i] = Math.random(); }
}

p.setup = function () {
  p.createCanvas(800, 800);
  p.pixelDensity(1);
  p.frameRate(60);
  hazeCanvas = document.createElement('canvas'); hazeCanvas.width = FG; hazeCanvas.height = FG;
  hazeCtx = hazeCanvas.getContext('2d'); hazeImg = hazeCtx.createImageData(FG, FG);
  scatter();
};

p.draw = function () {
  const plate = p.getSynthVar('plate') || 'square plate';
  const pitch = p.getSynthVar('pitch') || 'a song';
  const grain = p.getSynthVar('grain') || 'fine sand';
  const finish = p.getSynthVar('finish') || 'brass';
  const shake = p.getSynthVar('excitation') || 'a hum';
  const sweep = p.getSynthVar('sweep') || 'held steady';

  // plate changes crossfade over a second
  if (plate !== plateB) { plateA = plateB; plateB = plate; mix = 0; }
  if (mix < 1) mix = Math.min(1, mix + 0.02);

  // pitch glides toward its target; the sweep moves the target about
  const t = p.frameCount / 60;
  let target = PITCH[pitch] !== undefined ? PITCH[pitch] : 3.0;
  if (sweep === 'a slow drift') { target += Math.sin(t * 0.21) * 0.5; phase += 0.012; }
  else if (sweep === 'a rising sweep') target += (t % 24) / 24 * 3.4;
  else if (sweep === 'a falling sweep') target += 3.4 - (t % 24) / 24 * 3.4;
  else if (sweep === 'a wobble') target += Math.sin(t * 1.9) * 0.55;
  else if (sweep === 'a stepped arpeggio') { arp = Math.floor(t / 2.5) % 4; target += [0, 1.1, 2.3, 1.1][arp]; }
  else if (sweep === 'a random walk') { walk += (Math.random() - 0.5) * 0.06; walk *= 0.995; target += walk * 4; }
  q += (target - q) * 0.035;
  if (sweep !== 'a slow drift') phase += 0.004;

  const G = GRAINS[grain] || GRAINS['fine sand'];
  const F = FINISH[finish] || FINISH['brass'];
  const S = SHAKE[shake] !== undefined ? SHAKE[shake] : 1.0;
  const ctx = p.drawingContext;

  // plate and haze
  const bgGrad = ctx.createRadialGradient(400, 400, 40, 400, 400, 620);
  bgGrad.addColorStop(0, F.bg[0]); bgGrad.addColorStop(1, F.bg[1]);
  ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
  ctx.fillStyle = bgGrad; ctx.fillRect(0, 0, 800, 800);
  for (let j = 0; j < FG; j++) {
    const y = j * H - 1;
    for (let i = 0; i < FG; i++) fa[j * FG + i] = field(i * H - 1, y);
  }
  const d = hazeImg.data;
  for (let i = 0; i < FG * FG; i++) {
    const a = fa[i], tone = Math.min(1, Math.abs(a)) * 0.34, c = a > 0 ? F.pos : F.neg, o = i * 4;
    d[o] = c[0]; d[o + 1] = c[1]; d[o + 2] = c[2]; d[o + 3] = tone * 255;
  }
  hazeCtx.putImageData(hazeImg, 0, 0);
  ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(hazeCanvas, 0, 0, 800, 800);

  // grains: hop about in proportion to the plate's motion under them, and slide down the amplitude hill toward stillness
  const n = G.n, noise = 0.011 * S, slide = 0.0021 * Math.min(S, 2.2), wantAngle = grain === 'iron filings';
  const ink = F.ink;
  for (let i = 0; i < n; i++) {
    let x = gx[i], y = gy[i];
    const fx = (x + 1) / H, fy = (y + 1) / H;
    let ci = fx | 0, cj = fy | 0;
    if (ci < 0) ci = 0; else if (ci > FG - 2) ci = FG - 2;
    if (cj < 0) cj = 0; else if (cj > FG - 2) cj = FG - 2;
    const tx = fx - ci, ty = fy - cj, o = cj * FG + ci;
    const a00 = fa[o], a10 = fa[o + 1], a01 = fa[o + FG], a11 = fa[o + FG + 1];
    const a = (a00 * (1 - tx) + a10 * tx) * (1 - ty) + (a01 * (1 - tx) + a11 * tx) * ty;
    const gxv = ((a10 - a00) * (1 - ty) + (a11 - a01) * ty) / H, gyv = ((a01 - a00) * (1 - tx) + (a11 - a10) * tx) / H;
    let dx = -slide * a * gxv, dy = -slide * a * gyv;
    const dm = Math.abs(dx) + Math.abs(dy);
    if (dm > 0.03) { dx *= 0.03 / dm; dy *= 0.03 / dm; }
    const k = noise * (0.12 + 5 * (a < 0 ? -a : a));
    x += dx + (Math.random() - 0.5) * k; y += dy + (Math.random() - 0.5) * k;
    if (x < -DOM) x = -DOM + (-DOM - x); else if (x > DOM) x = DOM - (x - DOM);
    if (y < -DOM) y = -DOM + (-DOM - y); else if (y > DOM) y = DOM - (y - DOM);
    gx[i] = x; gy[i] = y;
    if (wantAngle) gAngle[i] = Math.atan2(gyv, gxv) + 1.5708;
  }

  const px = (x) => (x + 1) * 400, py = (y) => (y + 1) * 400, sz = G.size;
  if (grain === 'iron filings') {
    ctx.strokeStyle = `rgba(${ink[0]},${ink[1]},${ink[2]},0.8)`; ctx.lineWidth = 1.1; ctx.beginPath();
    for (let i = 0; i < n; i++) {
      const ang = gAngle[i], cx = px(gx[i]), cy = py(gy[i]), l = sz * 0.5;
      ctx.moveTo(cx - Math.cos(ang) * l, cy - Math.sin(ang) * l); ctx.lineTo(cx + Math.cos(ang) * l, cy + Math.sin(ang) * l);
    }
    ctx.stroke();
  } else if (grain === 'rice') {
    ctx.strokeStyle = `rgba(${ink[0]},${ink[1]},${ink[2]},0.85)`; ctx.lineWidth = 1.7; ctx.lineCap = 'round'; ctx.beginPath();
    for (let i = 0; i < n; i++) {
      const cx = px(gx[i]), cy = py(gy[i]), ang = gAngle[i], l = sz * 0.5;
      ctx.moveTo(cx - Math.cos(ang) * l, cy - Math.sin(ang) * l); ctx.lineTo(cx + Math.cos(ang) * l, cy + Math.sin(ang) * l);
    }
    ctx.stroke(); ctx.lineCap = 'butt';
  } else if (grain === 'glitter') {
    ctx.globalCompositeOperation = F.light ? 'source-over' : 'lighter';
    const tw = p.frameCount * 0.09;
    for (let b = 0; b < 6; b++) {
      ctx.fillStyle = `hsla(${b * 60 + (F.light ? 20 : 0)},${F.light ? 75 : 90}%,${F.light ? 42 : 66}%,${F.light ? 0.9 : 0.7})`;
      ctx.beginPath();
      for (let i = b; i < n; i += 6) {
        const s = sz * (0.55 + 0.45 * Math.sin(tw + gHue[i] * 40));
        ctx.rect(px(gx[i]) - s / 2, py(gy[i]) - s / 2, s, s);
      }
      ctx.fill();
    }
    ctx.globalCompositeOperation = 'source-over';
  } else if (grain === 'sugar crystals') {
    for (let b = 0; b < 4; b++) {
      const hue = [330, 200, 50, 150][b];
      ctx.fillStyle = F.light ? `hsla(${hue},55%,45%,0.9)` : `hsla(${hue},70%,80%,0.88)`;
      ctx.beginPath();
      for (let i = b; i < n; i += 4) ctx.rect(px(gx[i]) - sz / 2, py(gy[i]) - sz / 2, sz, sz);
      ctx.fill();
    }
  } else if (grain === 'pollen') {
    ctx.globalCompositeOperation = F.light ? 'source-over' : 'lighter';
    ctx.fillStyle = F.light ? 'rgba(190,120,0,0.85)' : 'rgba(255,214,90,0.7)'; ctx.beginPath();
    for (let i = 0; i < n; i++) { const cx = px(gx[i]), cy = py(gy[i]); ctx.moveTo(cx + sz / 2, cy); ctx.arc(cx, cy, sz / 2, 0, 6.2832); }
    ctx.fill(); ctx.globalCompositeOperation = 'source-over';
  } else if (grain === 'ink droplets') {
    ctx.fillStyle = `rgba(${ink[0]},${ink[1]},${ink[2]},0.8)`; ctx.beginPath();
    for (let i = 0; i < n; i++) { const cx = px(gx[i]), cy = py(gy[i]); ctx.moveTo(cx + sz / 2, cy); ctx.arc(cx, cy, sz / 2, 0, 6.2832); }
    ctx.fill();
  } else {                                      // 'fine sand' and 'salt'
    ctx.fillStyle = `rgba(${ink[0]},${ink[1]},${ink[2]},${grain === 'salt' ? 0.9 : 0.8})`; ctx.beginPath();
    for (let i = 0; i < n; i++) ctx.rect(px(gx[i]) - sz / 2, py(gy[i]) - sz / 2, sz, sz);
    ctx.fill();
  }

  // a round plate gets a rim
  if (plateB === 'round drum' || plateB === 'spiral chime') {
    ctx.strokeStyle = `rgba(${ink[0]},${ink[1]},${ink[2]},0.35)`; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(400, 400, 398, 0, 6.2832); ctx.stroke();
  }
};
